const DETAILS={"M. Deltoideus":{"bundles":["Pars clavicularis (voorste bundel)","Pars acromialis (middelste bundel)","Pars spinalis (achterste bundel)"],"origin":"Laterale 1/3 van de clavicula, acromion, spina scapulae","insertion":"Tuberositas deltoidea van de humerus","function":"Beweegt de bovenarm in alle richtingen, afhankelijk van welke bundel actief is.","direction":"Voorste bundel schuin naar voren-onder; middelste bundel verticaal omlaag; achterste bundel schuin naar achteren-onder.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray%20%E2%80%94%20deltoideus.png","imageCredit":"Gray's Anatomy, bewerkt door Helgo13 (publiek domein)"},"M. Pectoralis Major":{"bundles":["Pars clavicularis","Pars sternocostalis","Pars abdominalis"],"origin":"Clavicula, sternum, ribkraakbeen 1-6, rectusschede","insertion":"Crista tuberculi majoris humeri","function":"Adduceert, endoroteert en beweegt de arm horizontaal naar voren.","direction":"Waaiervormig van het borstbeen naar lateraal-boven naar de bovenarm.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray410%20pectoralis%20major.png","imageCredit":"Gray's Anatomy, H.V. Carter (publiek domein)"},"M. Latissimus Dorsi":{"bundles":null,"origin":"Processus spinosi Th7-L5, crista iliaca, onderste ribben, angulus inferior scapulae","insertion":"Crista tuberculi minoris humeri","function":"Adduceert, endoroteert en extendeert de arm; trekt de romp omhoog bij vaste arm (bijv. klimmen).","direction":"Van de onderrug/het bekken schuin naar boven-lateraal naar de bovenarm.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Latissimus%20dorsi%20muscle%20animation.gif","imageCredit":"Anatomography / BodyParts3D, DBCLS (CC BY-SA 2.1 JP)"},"M. Teres Major":{"bundles":null,"origin":"Angulus inferior scapulae","insertion":"Crista tuberculi minoris humeri","function":"Adduceert en endoroteert de arm; ondersteunt de Latissimus Dorsi.","direction":"Van de onderpunt van het schouderblad naar de mediale bovenarm.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Teres%20major.PNG","imageCredit":"Mikael Häggström, naar Gray's Anatomy (publiek domein)"},"M. Coracobrachialis":{"bundles":null,"origin":"Processus coracoideus","insertion":"Mediale zijde van de humerusschacht","function":"Adduceert en flecteert de arm licht.","direction":"Van de processus coracoideus schuin omlaag naar de mediale humerus.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray%20%E2%80%94%20musculus%20coracobrachialis.png","imageCredit":"Gray's Anatomy, bewerkt door Helgo13 (publiek domein)"},"M. Subscapularis":{"bundles":null,"origin":"Fossa subscapularis (voorzijde schouderblad)","insertion":"Tuberculum minus humeri","function":"Endoroteert de bovenarm; onderdeel van de rotator cuff.","direction":"Van de voorzijde van het schouderblad naar de voorzijde van de bovenarmkop.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray%20%E2%80%94%20musculus%20subscapularis.png","imageCredit":"Gray's Anatomy, bewerkt door Helgo13 (publiek domein)"},"M. Supraspinatus":{"bundles":null,"origin":"Fossa supraspinata","insertion":"Tuberculum majus humeri (bovenste facet)","function":"Initieert de abductie en centreert de kop in de kom; onderdeel van de rotator cuff.","direction":"Horizontaal onder het acromion door naar de bovenarmkop.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Supraspinatus%20muscle%20animation.gif","imageCredit":"Anatomography / BodyParts3D, DBCLS (CC BY-SA 2.1 JP)"},"M. Infraspinatus":{"bundles":null,"origin":"Fossa infraspinata","insertion":"Tuberculum majus humeri (middelste facet)","function":"Exoroteert de bovenarm; onderdeel van de rotator cuff.","direction":"Van de achterzijde van het schouderblad naar de achterzijde van de bovenarmkop.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray%20%E2%80%94%20musculus%20infraspinatus.png","imageCredit":"Gray's Anatomy, bewerkt door Helgo13 (publiek domein)"},"M. Teres Minor":{"bundles":null,"origin":"Laterale rand van de scapula","insertion":"Tuberculum majus humeri (onderste facet)","function":"Exoroteert de bovenarm; onderdeel van de rotator cuff.","direction":"Vergelijkbaar met de Infraspinatus, net iets lager gelegen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Teres%20minor%20muscle%20animation2.gif","imageCredit":"Anatomography / BodyParts3D, DBCLS (CC BY-SA 2.1 JP)"},"M. Trapezius":{"bundles":["Pars descendens (bovenste)","Pars transversa (middelste)","Pars ascendens (onderste)"],"origin":"Os occipitale, ligamentum nuchae, processus spinosi C7-Th12","insertion":"Laterale clavicula, acromion, spina scapulae","function":"Beweegt en stabiliseert het schouderblad (elevatie, retractie, depressie, opwaartse rotatie).","direction":"Bovenste vezels schuin omlaag-lateraal, middelste horizontaal, onderste schuin omhoog-lateraal.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Trapezius%20Gray409.PNG","imageCredit":"Mikael Häggström, naar Gray's Anatomy (publiek domein)"},"M. Levator Scapulae":{"bundles":null,"origin":"Processus transversi C1-C4","insertion":"Angulus superior scapulae","function":"Heft het schouderblad; buigt de nek zijwaarts.","direction":"Van de bovenste halswervels schuin omlaag naar het schouderblad.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Levator%20scapulae.png","imageCredit":"Gray's Anatomy, bewerkt door Uwe Gille (publiek domein)"},"Mm. Rhomboidei":{"bundles":["M. Rhomboideus Major","M. Rhomboideus Minor"],"origin":"Processus spinosi C7-Th5","insertion":"Mediale rand van de scapula","function":"Retraheren en heffen het schouderblad.","direction":"Van de wervelkolom schuin naar lateraal-boven naar het schouderblad.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rhomboideus%20major.png","imageCredit":"Gray's Anatomy, bewerkt door Uwe Gille (publiek domein)"},"M. Pectoralis Minor":{"bundles":null,"origin":"Ribben 3-5","insertion":"Processus coracoideus","function":"Trekt het schouderblad naar voren-onder (protractie/depressie); hulpademhalingsspier.","direction":"Van de ribben schuin omhoog naar de processus coracoideus.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pectoralis%20minor%20muscle%20animation.gif","imageCredit":"Anatomography / BodyParts3D, DBCLS (CC BY-SA 2.1 JP)"},"M. Serratus Anterior":{"bundles":null,"origin":"Laterale zijde van ribben 1-9","insertion":"Mediale rand van de scapula (voorzijde)","function":"Protraheert het schouderblad en roteert het opwaarts (bijv. bij stoten/duwen).","direction":"Van de zijkant van de ribbenkast naar de mediale rand van het schouderblad.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Serratus%20anterior%20muscle%20animation.gif","imageCredit":"Anatomography / BodyParts3D, DBCLS (CC BY-SA 2.1 JP)"},"M. Biceps Brachii":{"bundles":["Caput longum","Caput breve"],"origin":"Caput longum: tuberculum supraglenoidale; caput breve: processus coracoideus","insertion":"Tuberositas radii en aponeurosis bicipitalis","function":"Flecteert elleboog en schouder; supineert de onderarm.","direction":"Verticaal over de voorzijde van de bovenarm naar de radius.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray%20%E2%80%94%20musculus%20biceps%20brachii.png","imageCredit":"Gray's Anatomy, bewerkt door Helgo13 (publiek domein)"},"M. Brachialis":{"bundles":null,"origin":"Voorzijde van de distale humerus","insertion":"Tuberositas ulnae","function":"Zuivere elleboogflexor, ongeacht de stand van de onderarm.","direction":"Verticaal onder de biceps door naar de ulna.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray%20%E2%80%94%20musculus%20brachialis.png","imageCredit":"Gray's Anatomy, bewerkt door Helgo13 (publiek domein)"},"M. Brachioradialis":{"bundles":null,"origin":"Laterale supracondylaire rand van de humerus","insertion":"Processus styloideus radii","function":"Flecteert de elleboog, met name vanuit de middenstand tussen pro- en supinatie.","direction":"Van de laterale bovenarm schuin naar de pols.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray%20%E2%80%94%20musculus%20brachioradialis.png","imageCredit":"Gray's Anatomy, bewerkt door Helgo13 (publiek domein)"},"M. Triceps Brachii":{"bundles":["Caput longum","Caput laterale","Caput mediale"],"origin":"Caput longum: tuberculum infraglenoidale; laterale/mediale kop: achterzijde humerusschacht","insertion":"Olecranon van de ulna","function":"Strekt de elleboog; de lange kop strekt ook licht de schouder.","direction":"Verticaal over de achterzijde van de bovenarm naar de elleboogpunt.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray%20%E2%80%94%20musculus%20triceps%20brachii.png","imageCredit":"Gray's Anatomy, bewerkt door Helgo13 (publiek domein)"},"M. Anconeus":{"bundles":null,"origin":"Laterale epicondylus humeri","insertion":"Olecranon en proximale ulna","function":"Ondersteunt de elleboogextensie en stabiliseert het gewricht.","direction":"Kort, schuin van de laterale epicondyl naar de ulna.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray%20%E2%80%94%20musculus%20anconeus.png","imageCredit":"Gray's Anatomy, bewerkt door Helgo13 (publiek domein)"},"M. Supinator":{"bundles":null,"origin":"Laterale epicondylus humeri, crista m. supinatoris van de ulna","insertion":"Proximale 1/3 van de radius","function":"Supineert de onderarm.","direction":"Wikkelt schuin om de radiuskop heen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray%20%E2%80%94%20musculus%20supinator.png","imageCredit":"Gray's Anatomy, bewerkt door Helgo13 (publiek domein)"},"M. Pronator Teres":{"bundles":null,"origin":"Mediale epicondylus humeri, processus coronoideus ulnae","insertion":"Laterale zijde van de radiusschacht","function":"Proneert de onderarm en flecteert licht de elleboog.","direction":"Schuin van mediaal-boven naar lateraal-onder over de onderarm.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray%20%E2%80%94%20musculus%20pronator%20teres.png","imageCredit":"Gray's Anatomy, bewerkt door Helgo13 (publiek domein)"},"M. Pronator Quadratus":{"bundles":null,"origin":"Distale ulna","insertion":"Distale radius","function":"Belangrijkste pronator van de onderarm.","direction":"Horizontaal tussen ulna en radius, net boven de pols.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray%20%E2%80%94%20musculus%20pronator%20quadratus.png","imageCredit":"Gray's Anatomy, bewerkt door Helgo13 (publiek domein)"},"M. Flexor Carpi Radialis":{"bundles":null,"origin":"Mediale epicondylus humeri","insertion":"Basis van os metacarpale II","function":"Palmairflecteert en radiaal-deviaert de pols.","direction":"Schuin van de mediale elleboog naar de duimzijde van de hand.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray%20%E2%80%94%20musculus%20flexor%20carpi%20radialis.png","imageCredit":"Gray's Anatomy, bewerkt door Helgo13 (publiek domein)"},"M. Flexor Carpi Ulnaris":{"bundles":null,"origin":"Mediale epicondylus humeri, olecranon","insertion":"Os pisiforme, basis metacarpale V","function":"Palmairflecteert en ulnair-deviaert de pols.","direction":"Van de mediale elleboog naar de pinkzijde van de hand.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray%20%E2%80%94%20musculus%20flexor%20carpi%20ulnaris.png","imageCredit":"Gray's Anatomy, bewerkt door Helgo13 (publiek domein)"},"M. Palmaris Longus":{"bundles":null,"origin":"Mediale epicondylus humeri","insertion":"Aponeurosis palmaris","function":"Spant de palmaire fascie; zwakke polsflexor (bij circa 15% van de mensen afwezig).","direction":"Verticaal midden over de onderarm en pols.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray%20%E2%80%94%20musculus%20palmaris%20longus.png","imageCredit":"Gray's Anatomy, bewerkt door Helgo13 (publiek domein)"},"M. Flexor Digitorum Superficialis / Profundus":{"bundles":["Superficialis","Profundus"],"origin":"Superficialis: mediale epicondylus/ulna/radius; profundus: ulna en membrana interossea","insertion":"Superficialis: middenfalanx; profundus: eindfalanx van vingers II-V","function":"Flecteren de vingers en ondersteunen de polsflexie.","direction":"Van de onderarm naar de vingertoppen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray%20%E2%80%94%20musculus%20flexor%20digitorum%20superficialis.png","imageCredit":"Gray's Anatomy, bewerkt door Helgo13 (publiek domein)"},"M. Extensor Carpi Radialis Longus":{"bundles":null,"origin":"Laterale supracondylaire rand van de humerus","insertion":"Basis van os metacarpale II","function":"Dorsaalflecteert en radiaal-deviaert de pols.","direction":"Van de laterale bovenarm naar de duimzijde van de handrug.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray%20%E2%80%94%20musculus%20extensor%20carpi%20radialis%20longus.png","imageCredit":"Gray's Anatomy, bewerkt door Helgo13 (publiek domein)"},"M. Extensor Carpi Radialis Longus / Brevis":{"bundles":["Longus","Brevis"],"origin":"Laterale supracondylaire rand (longus) / laterale epicondylus humeri (brevis)","insertion":"Basis metacarpale II (longus) / III (brevis)","function":"Dorsaalflecteren en radiaal-deviaren de pols.","direction":"Van de laterale bovenarm naar de duimzijde van de handrug.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray%20%E2%80%94%20musculus%20extensor%20carpi%20radialis%20longus.png","imageCredit":"Gray's Anatomy, bewerkt door Helgo13 (publiek domein)"},"M. Extensor Carpi Ulnaris":{"bundles":null,"origin":"Laterale epicondylus humeri, ulna","insertion":"Basis van os metacarpale V","function":"Dorsaalflecteert en ulnair-deviaert de pols.","direction":"Naar de pinkzijde van de handrug.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray%20%E2%80%94%20musculus%20extensor%20carpi%20ulnaris.png","imageCredit":"Gray's Anatomy, bewerkt door Helgo13 (publiek domein)"},"M. Extensor Digitorum":{"bundles":null,"origin":"Laterale epicondylus humeri","insertion":"Dorsale aponeurose van vingers II-V","function":"Strekt de vingers en ondersteunt de polsextensie.","direction":"Waaiervormig naar de vingertoppen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Musculus%20extensor%20digitorum.PNG","imageCredit":"Gray's Anatomy, H.V. Carter (publiek domein)"},"M. Abductor Pollicis Longus":{"bundles":null,"origin":"Achterzijde van radius en ulna","insertion":"Basis van os metacarpale I","function":"Abduceert en extendeert de duim.","direction":"Schuin naar de duimzijde van de pols.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray%20%E2%80%94%20musculus%20abductor%20pollicis%20longus.png","imageCredit":"Gray's Anatomy, bewerkt door Helgo13 (publiek domein)"},"M. Extensor Pollicis Longus":{"bundles":null,"origin":"Ulna","insertion":"Eindfalanx van de duim","function":"Strekt de duim.","direction":"Naar de top van de duim.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray%20%E2%80%94%20musculus%20extensor%20pollicis%20longus.png","imageCredit":"Gray's Anatomy, bewerkt door Helgo13 (publiek domein)"},"M. Sternocleidomastoideus":{"bundles":null,"origin":"Sternum en clavicula","insertion":"Processus mastoideus en linea nuchae","function":"Bilateraal: buigt de nek voorover. Unilateraal: kantelt zijwaarts en roteert naar de tegenoverliggende zijde.","direction":"Schuin van het borstbeen/sleutelbeen omhoog naar achter het oor.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sternocleidomastoideus.png","imageCredit":"Gray's Anatomy, bewerkt door Uwe Gille (publiek domein)"},"Mm. Scaleni":{"bundles":["Anterior","Medius","Posterior"],"origin":"Processus transversi van de cervicale wervels","insertion":"Ribben 1 en 2","function":"Lateroflecteren de nek; hulpademhalingsspieren.","direction":"Verticaal langs de zijkant van de nek naar de bovenste ribben.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray%20%E2%80%94%20musculus%20scalenus%20anterior.png","imageCredit":"Gray's Anatomy, bewerkt door Helgo13 (publiek domein)"},"M. Longus Colli":{"bundles":null,"origin":"Voorzijde van de wervellichamen C1-Th3","insertion":"Voorzijde van de wervellichamen C1-Th3 (hoger gelegen)","function":"Diepe flexor en stabilisator van de cervicale wervelkolom.","direction":"Verticaal langs de voorzijde van de halswervels.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Longus%20colli.png","imageCredit":"Gray's Anatomy, bewerkt door Uwe Gille (publiek domein)"},"M. Longus Capitis":{"bundles":null,"origin":"Processus transversi C3-C6","insertion":"Os occipitale","function":"Flecteert het hoofd en de bovenste nek.","direction":"Van de halswervels naar de schedelbasis.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Longus%20capitis.png","imageCredit":"Gray's Anatomy, bewerkt door Uwe Gille (publiek domein)"},"M. Splenius Capitis":{"bundles":null,"origin":"Processus spinosi C7-Th6","insertion":"Processus mastoideus","function":"Extendeert en roteert het hoofd naar dezelfde zijde.","direction":"Schuin van onder-mediaal naar boven-lateraal.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Musculus%20splenius%20capitis%20marked.png","imageCredit":"Gray's Anatomy, bewerkt door Uwe Gille (publiek domein)"},"M. Splenius Capitis / Cervicis":{"bundles":["Capitis","Cervicis"],"origin":"Processus spinosi C7-Th6","insertion":"Processus mastoideus (capitis) / processus transversi C1-C3 (cervicis)","function":"Extenderen en roteren hoofd/nek naar dezelfde zijde.","direction":"Schuin van onder-mediaal naar boven-lateraal.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Musculus%20splenius%20capitis%20et%20cervicis.png","imageCredit":"Gray's Anatomy, H.V. Carter (publiek domein)"},"M. Semispinalis Capitis":{"bundles":null,"origin":"Processus transversi C7-Th6","insertion":"Os occipitale","function":"Extendeert hoofd en nek.","direction":"Verticaal langs de achterzijde van de nek.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray389%20Semispinalis%20capitis.png","imageCredit":"Gray's Anatomy, H.V. Carter (publiek domein)"},"Mm. Rotatores":{"bundles":null,"origin":"Processus transversus van een wervel","insertion":"Processus spinosus van de aangrenzende (of 2e) hoger gelegen wervel","function":"Kleine, diepe rotatoren en segmentale stabilisatoren van de wervelkolom.","direction":"Kort, schuin tussen naburige wervels.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rotatores.png","imageCredit":"Anatomography / BodyParts3D, DBCLS (CC BY-SA 2.1 JP)"},"Mm. Rotatores Lumbales":{"bundles":null,"origin":"Processus transversus van een lumbale wervel","insertion":"Processus spinosus van de aangrenzende wervel","function":"Kleine, diepe rotatoren en stabilisatoren van de lumbale wervelkolom.","direction":"Kort, schuin tussen naburige lumbale wervels.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rotatores.png","imageCredit":"Anatomography / BodyParts3D, DBCLS (CC BY-SA 2.1 JP)"},"Mm. Rotatores Thoracales":{"bundles":null,"origin":"Processus transversus van een thoracale wervel","insertion":"Processus spinosus van de aangrenzende wervel","function":"Kleine, diepe rotatoren en stabilisatoren van de thoracale wervelkolom.","direction":"Kort, schuin tussen naburige thoracale wervels.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rotatores.png","imageCredit":"Anatomography / BodyParts3D, DBCLS (CC BY-SA 2.1 JP)"},"M. Rectus Abdominis":{"bundles":null,"origin":"Os pubis","insertion":"Ribkraakbeen 5-7, processus xiphoideus","function":"Flecteert de romp; stabiliseert het bekken.","direction":"Verticaal van het schaambeen naar het borstbeen/de ribben.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rectus%20abdominis.png","imageCredit":"Wikimedia Commons (CC BY-SA 3.0)"},"M. Obliquus Externus Abdominis":{"bundles":null,"origin":"Ribben 5-12","insertion":"Crista iliaca, linea alba","function":"Flecteert de romp, roteert naar de tegenoverliggende zijde en lateroflecteert.","direction":"Schuin naar mediaal-onder (richting 'handen-in-zakken').","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray392.png","imageCredit":"Gray's Anatomy, H.V. Carter (publiek domein)"},"M. Obliquus Internus Abdominis":{"bundles":null,"origin":"Crista iliaca, ligamentum inguinale","insertion":"Ribben 10-12, linea alba","function":"Flecteert de romp, roteert naar dezelfde zijde en lateroflecteert.","direction":"Loodrecht op de externus, schuin naar mediaal-boven.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray395.png","imageCredit":"Gray's Anatomy, H.V. Carter (publiek domein)"},"M. Transversus Abdominis":{"bundles":null,"origin":"Crista iliaca, ligamentum inguinale, ribkraakbeen 7-12","insertion":"Linea alba","function":"Comprimeert de buikinhoud en verhoogt de intra-abdominale druk (korset-functie).","direction":"Horizontaal rond de romp.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Transversus%20abdominis.png","imageCredit":"Gray's Anatomy, bewerkt door Uwe Gille (publiek domein)"},"M. Quadratus Lumborum":{"bundles":null,"origin":"Crista iliaca","insertion":"12e rib, processus transversi L1-L4","function":"Lateroflecteert de romp; stabiliseert het bekken tijdens het lopen.","direction":"Verticaal langs de achterste buikwand.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Quadratuslumborum.png","imageCredit":"Gray's Anatomy, bewerkt door Uwe Gille (publiek domein)"},"M. Erector Spinae":{"bundles":["M. Iliocostalis","M. Longissimus","M. Spinalis"],"origin":"Crista iliaca, os sacrum, processus spinosi","insertion":"Ribben en processus transversi/spinosi van hoger gelegen wervels","function":"Extendeert en stabiliseert de wervelkolom; unilateraal lateroflexie.","direction":"Verticaal, in drie parallelle kolommen (van lateraal naar mediaal: iliocostalis, longissimus, spinalis).","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray389%20-%20Erector%20spinae.png","imageCredit":"Gray's Anatomy, H.V. Carter (publiek domein)"},"M. Iliocostalis Lumborum":{"bundles":null,"origin":"Os sacrum, crista iliaca","insertion":"Onderste ribben","function":"Extendeert en lateroflecteert de lumbale wervelkolom; onderdeel van de Erector Spinae.","direction":"Verticaal, meest lateraal gelegen van de drie erector-kolommen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Iliostalis.png","imageCredit":"Gray's Anatomy, bewerkt door Uwe Gille (publiek domein)"},"M. Iliocostalis Thoracis":{"bundles":null,"origin":"Onderste ribben","insertion":"Bovenste ribben","function":"Extendeert en lateroflecteert de thoracale wervelkolom; onderdeel van de Erector Spinae.","direction":"Verticaal, meest lateraal gelegen van de drie erector-kolommen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Iliostalis.png","imageCredit":"Gray's Anatomy, bewerkt door Uwe Gille (publiek domein)"},"M. Longissimus Lumborum":{"bundles":null,"origin":"Os sacrum, processus transversi lumbaal","insertion":"Processus transversi hoger gelegen lumbale/thoracale wervels","function":"Extendeert de lumbale wervelkolom; onderdeel van de Erector Spinae.","direction":"Verticaal, middelste kolom van de Erector Spinae.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Longissimus.png","imageCredit":"Gray's Anatomy, bewerkt door Uwe Gille (publiek domein)"},"M. Longissimus Thoracis":{"bundles":null,"origin":"Os sacrum, processus transversi lumbaal","insertion":"Processus transversi thoracale wervels en onderste ribben","function":"Extendeert de thoracale wervelkolom; onderdeel van de Erector Spinae.","direction":"Verticaal, middelste kolom van de Erector Spinae.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Longissimus.png","imageCredit":"Gray's Anatomy, bewerkt door Uwe Gille (publiek domein)"},"M. Spinalis Thoracis":{"bundles":null,"origin":"Processus spinosi Th11-L2","insertion":"Processus spinosi bovenste thoracale wervels","function":"Extendeert de thoracale wervelkolom; onderdeel van de Erector Spinae.","direction":"Verticaal, meest mediale kolom van de Erector Spinae, vlak naast de doornuitsteeksels.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Spinalis.png","imageCredit":"Gray's Anatomy, bewerkt door Uwe Gille (publiek domein)"},"M. Multifidus":{"bundles":null,"origin":"Os sacrum, processus transversi","insertion":"Processus spinosi, 2-4 wervels hoger","function":"Segmentale stabilisatie van de wervelkolom; diepe extensor/rotator.","direction":"Kort, schuin van onder-lateraal naar boven-mediaal.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Multifidi.png","imageCredit":"Gray's Anatomy, bewerkt door Uwe Gille (publiek domein)"},"Mm. Intercostales":{"bundles":["Externi","Interni"],"origin":"Onderrand van een rib","insertion":"Bovenrand van de eronder gelegen rib","function":"Ademhalingsspieren; stabiliseren de ribbenkast bij rompbeweging.","direction":"Schuin tussen aangrenzende ribben.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/External%20intercostal%20muscles%20animation.gif","imageCredit":"Anatomography / BodyParts3D, DBCLS (CC BY-SA 2.1 JP)"},"M. Psoas Major":{"bundles":null,"origin":"Processus transversi en corpora van wervels Th12-L5","insertion":"Trochanter minor femoris","function":"Flecteert de heup; bilateraal ook een lichte lumbale flexor/stabilisator.","direction":"Van de lumbale wervelkolom schuin naar beneden-lateraal naar het bovenbeen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Psoas%20major%20muscle%20-%20animation07.gif","imageCredit":"Anatomography / BodyParts3D, DBCLS (CC BY-SA 2.1 JP)"},"M. Iliopsoas":{"bundles":["M. Iliacus","M. Psoas Major"],"origin":"Fossa iliaca (iliacus) en processus transversi/corpora L1-L5 (psoas major)","insertion":"Trochanter minor femoris","function":"Sterkste heupflexor.","direction":"Van bekken/onderrug schuin naar beneden-lateraal naar het bovenbeen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Psoas%20major%20muscle%20-%20animation07.gif","imageCredit":"Anatomography / BodyParts3D, DBCLS (CC BY-SA 2.1 JP) — toont M. Psoas Major, het grootste deel van de Iliopsoas"},"M. Rectus Femoris":{"bundles":null,"origin":"Spina iliaca anterior inferior","insertion":"Tuberositas tibiae (via de patella)","function":"Enige quadricepskop die ook de heup flecteert; strekt daarnaast de knie.","direction":"Verticaal over de voorzijde van het bovenbeen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rectus%20femoris%203D.gif","imageCredit":"Anatomography / BodyParts3D, DBCLS (CC BY-SA 2.1 JP)"},"M. Gluteus Maximus":{"bundles":null,"origin":"Os ilium, os sacrum","insertion":"Tractus iliotibialis, tuberositas glutealis femoris","function":"Krachtigste heupextensor en -exorotator; stabiliseert bekken en knie via de tractus iliotibialis.","direction":"Schuin van het bekken naar beneden-lateraal naar het bovenbeen/de tractus iliotibialis.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gluteus%20maximus%20muscle.PNG","imageCredit":"Mikael Häggström, naar Gray's Anatomy (publiek domein)"},"M. Gluteus Medius":{"bundles":null,"origin":"Buitenzijde van het os ilium","insertion":"Trochanter major femoris","function":"Belangrijkste heupabductor; stabiliseert het bekken tijdens eenbenig staan en lopen.","direction":"Waaiervormig van de bekkenkam naar de grote rolheuvel.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gluteus%20medius%20muscle%20-%20animation01.gif","imageCredit":"Anatomography / BodyParts3D, DBCLS (CC BY-SA 2.1 JP)"},"M. Gluteus Minimus":{"bundles":null,"origin":"Buitenzijde van het os ilium","insertion":"Trochanter major femoris","function":"Ondersteunt heupabductie en -endorotatie; stabiliseert het bekken.","direction":"Waaiervormig van de bekkenkam naar de grote rolheuvel, onder de Gluteus Medius.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gluteus%20minimus%20muscle.PNG","imageCredit":"Mikael Häggström, naar Gray's Anatomy (publiek domein)"},"M. Tensor Fasciae Latae":{"bundles":null,"origin":"Spina iliaca anterior superior","insertion":"Tractus iliotibialis","function":"Flecteert, abduceert en endoroteert de heup; spant de tractus iliotibialis.","direction":"Van het bekken schuin naar beneden in de tractus iliotibialis.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray430%20with%20TensorFasciaLata.png","imageCredit":"Jmarchn, naar Gray's Anatomy (CC BY-SA 3.0)"},"Hamstrings":{"bundles":["M. Biceps Femoris (caput longum & breve)","M. Semitendinosus","M. Semimembranosus"],"origin":"Tuber ischiadicum (caput breve biceps femoris ontspringt op de linea aspera van het femur)","insertion":"Caput fibulae (biceps femoris) / mediale tibiacondyl (semitendinosus, semimembranosus)","function":"Extenderen de heup en flecteren de knie.","direction":"Verticaal over de achterzijde van het bovenbeen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hamstrings.gif","imageCredit":"Anatomography / BodyParts3D, DBCLS (CC BY-SA 2.1 JP)"},"M. Biceps Femoris":{"bundles":["Caput longum","Caput breve"],"origin":"Caput longum: tuber ischiadicum; caput breve: linea aspera femoris","insertion":"Caput fibulae","function":"Flecteert en exoroteert de knie; caput longum extendeert ook de heup.","direction":"Verticaal over de achter-buitenzijde van het bovenbeen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Biceps%20femoris%20muscle%20long%20head.PNG","imageCredit":"Gray's Anatomy, H.V. Carter (publiek domein)"},"M. Semitendinosus":{"bundles":null,"origin":"Tuber ischiadicum","insertion":"Pes anserinus (mediale tibia)","function":"Extendeert de heup en flecteert/endoroteert de knie.","direction":"Verticaal over de achter-binnenzijde van het bovenbeen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Semitendinosus%20muscle.PNG","imageCredit":"Mikael Häggström, naar Gray's Anatomy (publiek domein)"},"M. Semimembranosus":{"bundles":null,"origin":"Tuber ischiadicum","insertion":"Mediale tibiacondyl","function":"Extendeert de heup en flecteert/endoroteert de knie.","direction":"Verticaal, dieper gelegen dan de Semitendinosus, over de achter-binnenzijde van het bovenbeen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Semimembranosus.gif","imageCredit":"Anatomography / BodyParts3D, DBCLS (CC BY-SA 2.1 JP)"},"Adductoren":{"bundles":["M. Adductor Longus","M. Adductor Brevis","M. Adductor Magnus"],"origin":"Os pubis (en tuber ischiadicum voor de achterste vezels van de magnus)","insertion":"Linea aspera femoris (en adductor tubercle voor de magnus)","function":"Adduceren de heup; de achterste vezels van de magnus extenderen ook licht.","direction":"Van het schaambeen schuin naar lateraal-onder naar het dijbeen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Adductores%20femoris.png","imageCredit":"Gray's Anatomy, ingekleurd door Michael Gasperl (publiek domein)"},"M. Adductor Magnus":{"bundles":["Adductorisch deel","Hamstring-deel (dorsale vezels)"],"origin":"Os pubis, tuber ischiadicum","insertion":"Linea aspera en adductor tubercle femoris","function":"Adduceert de heup; het dorsale deel extendeert ook licht.","direction":"Van het bekken schuin naar het dijbeen, met een verticaal deel richting de knie.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Adductor%20magnus.gif","imageCredit":"Anatomography / BodyParts3D, DBCLS (CC BY-SA 2.1 JP)"},"M. Adductor Longus":{"bundles":null,"origin":"Os pubis","insertion":"Linea aspera femoris (middelste 1/3)","function":"Adduceert de heup en flecteert deze licht.","direction":"Schuin van het schaambeen naar het middenderde van het dijbeen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Adductor%20longus.gif","imageCredit":"Anatomography / BodyParts3D, DBCLS (CC BY-SA 2.1 JP)"},"M. Adductor Brevis":{"bundles":null,"origin":"Os pubis","insertion":"Linea aspera femoris (bovenste 1/3)","function":"Adduceert de heup.","direction":"Kort, schuin van het schaambeen naar het bovenste dijbeen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Adductor%20brevis.gif","imageCredit":"Anatomography / BodyParts3D, DBCLS (CC BY-SA 2.1 JP)"},"M. Gracilis":{"bundles":null,"origin":"Os pubis","insertion":"Pes anserinus (mediale tibia)","function":"Adduceert de heup; flecteert en endoroteert de knie.","direction":"Lang en dun, verticaal langs de binnenzijde van het hele bovenbeen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gracilis.gif","imageCredit":"Anatomography / BodyParts3D, DBCLS (CC BY-SA 2.1 JP)"},"M. Pectineus":{"bundles":null,"origin":"Ramus superior van het os pubis","insertion":"Linea pectinea femoris","function":"Adduceert en flecteert de heup.","direction":"Kort, schuin van het schaambeen naar het bovenste dijbeen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pectineus%203D.gif","imageCredit":"Anatomography / BodyParts3D, DBCLS (CC BY-SA 2.1 JP)"},"M. Sartorius":{"bundles":null,"origin":"Spina iliaca anterior superior","insertion":"Pes anserinus (mediale tibia)","function":"Flecteert, abduceert en exoroteert de heup; flecteert de knie ('kleermakersspier').","direction":"Diagonaal over de voorzijde van het hele bovenbeen, van lateraal-boven naar mediaal-onder.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sartorius%203D.gif","imageCredit":"Anatomography / BodyParts3D, DBCLS (CC BY-SA 2.1 JP)"},"M. Piriformis":{"bundles":null,"origin":"Voorzijde van het os sacrum","insertion":"Trochanter major femoris","function":"Exoroteert de heup; abduceert bij gebogen heup.","direction":"Van het heiligbeen schuin naar lateraal naar de rolheuvel.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Piriformis%20muscle.PNG","imageCredit":"Mikael Häggström, naar Gray's Anatomy (publiek domein)"},"Diepe pelvitrochantaire spieren":{"bundles":["M. Obturatorius Internus","M. Obturatorius Externus","Mm. Gemelli"],"origin":"Rondom het foramen obturatum","insertion":"Fossa trochanterica femoris","function":"Exoroteren de heup; stabiliseren de heupkop in de kom.","direction":"Van rond het bekkengat naar de achterzijde van de rolheuvel.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Obturator%20internus%20muscle.png","imageCredit":"Mikael Häggström, naar Gray's Anatomy (publiek domein)"},"M. Quadratus Femoris":{"bundles":null,"origin":"Tuber ischiadicum","insertion":"Crista intertrochanterica femoris","function":"Exoroteert de heup.","direction":"Nagenoeg horizontaal van de zitbeenknobbel naar het dijbeen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Quadratus%20femoris%20muscle.PNG","imageCredit":"Mikael Häggström, naar Gray's Anatomy (publiek domein)"},"M. Vastus Lateralis / Medialis / Intermedius":{"bundles":["Vastus Lateralis","Vastus Medialis","Vastus Intermedius"],"origin":"Linea aspera en de mediale/laterale lip van de femurschacht","insertion":"Tuberositas tibiae (via de patella)","function":"Strekken de knie; hebben geen invloed op de heup.","direction":"Verticaal langs de voor-, binnen- en buitenzijde van het bovenbeen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Quadriceps.png","imageCredit":"Gray's Anatomy, ingekleurd door Michael Gasperl (publiek domein)"},"M. Popliteus":{"bundles":null,"origin":"Laterale femurcondyl","insertion":"Achterzijde van de proximale tibia","function":"'Ontgrendelt' de knie door endorotatie van het onderbeen bij het inzetten van flexie.","direction":"Schuin achter de knie, van lateraal naar mediaal-onder.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray439-Musculus%20popliteus.png","imageCredit":"Gray's Anatomy, H.V. Carter (publiek domein)"},"M. Gastrocnemius":{"bundles":["Caput mediale","Caput laterale"],"origin":"Mediale en laterale femurcondyl","insertion":"Calcaneus (via de achillespees)","function":"Plantairflecteert de enkel; flecteert ook licht de knie.","direction":"Verticaal over de achterzijde van de kuit naar de hiel.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gastrocnemius.png","imageCredit":"Wikimedia Commons (CC BY-SA 3.0)"},"M. Soleus":{"bundles":null,"origin":"Achterzijde van tibia en fibula","insertion":"Calcaneus (via de achillespees)","function":"Plantairflecteert de enkel, actief ongeacht de kniestand; belangrijk bij staan.","direction":"Onder de Gastrocnemius, verticaal naar de hiel.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Soleus%20muscle%20-%20animation.gif","imageCredit":"Anatomography / BodyParts3D, DBCLS (CC BY-SA 2.1 JP)"},"M. Triceps Surae":{"bundles":["M. Gastrocnemius","M. Soleus"],"origin":"Femurcondylen (gastrocnemius) en achterzijde tibia/fibula (soleus)","insertion":"Calcaneus (via de achillespees)","function":"Gezamenlijke naam voor de kuitspieren; krachtigste plantairflexoren van de enkel.","direction":"Verticaal naar de hiel via de achillespees.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Triceps%20surae.svg","imageCredit":"Anatomography / BodyParts3D, DBCLS (CC BY-SA 2.1 JP)"},"M. Tibialis Anterior":{"bundles":null,"origin":"Laterale tibiacondyl","insertion":"Os cuneiforme mediale en os metatarsale I","function":"Dorsaalflecteert en inverteert de voet.","direction":"Van net onder de knie schuin naar de binnenzijde van de voetrug.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tibialis%20anterior%20muscle%20-%20animation.gif","imageCredit":"Anatomography / BodyParts3D, DBCLS (CC BY-SA 2.1 JP)"},"M. Tibialis Posterior":{"bundles":null,"origin":"Membrana interossea, tibia en fibula","insertion":"Os naviculare en overige tarsalia","function":"Plantairflecteert en inverteert de voet; ondersteunt het mediale voetgewelf.","direction":"Achter de mediale malleolus naar de voetzool.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tibialis%20posterior.png","imageCredit":"Gray's Anatomy, bewerkt door Uwe Gille (publiek domein)"},"M. Peroneus Longus":{"bundles":null,"origin":"Laterale fibula","insertion":"Os metatarsale I en os cuneiforme mediale","function":"Everteert de voet en ondersteunt de dwarsboog.","direction":"Achter de laterale malleolus, kruist onder de voetzool naar mediaal.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray439-Musculus%20peroneus%20longus.png","imageCredit":"Gray's Anatomy, H.V. Carter (publiek domein)"},"M. Peroneus Brevis":{"bundles":null,"origin":"Laterale fibula","insertion":"Os metatarsale V","function":"Everteert de voet.","direction":"Achter de laterale malleolus naar de buitenzijde van de voet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fibularis%20brevis%20muscle%20-%20animation.gif","imageCredit":"Anatomography / BodyParts3D, DBCLS (CC BY-SA 2.1 JP)"},"M. Peroneus Longus / Brevis":{"bundles":["Longus","Brevis"],"origin":"Laterale fibula","insertion":"Os metatarsale I / os cuneiforme mediale (longus); os metatarsale V (brevis)","function":"Everteren de voet; de longus ondersteunt bovendien de dwarsboog.","direction":"Achter de laterale malleolus; de longus kruist onder de voet naar mediaal.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray439-Musculus%20peroneus%20longus.png","imageCredit":"Gray's Anatomy, H.V. Carter (publiek domein)"},"M. Peroneus Tertius":{"bundles":null,"origin":"Distale derde van de voorzijde van de fibula en de membrana interossea","insertion":"Dorsale zijde van de basis van os metatarsale V","function":"Dorsaalflexie en pronatie van de voet; werkt samen met de M. Extensor Digitorum Longus (soms als deel daarvan beschouwd, ontbreekt bij een deel van de mensen).","direction":"Langs de voorzijde van het onderbeen, voor de laterale malleolus naar de buitenzijde van de voetrug.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Peroneus%20tertius.png","imageCredit":"Gray's Anatomy, bewerkt door Uwe Gille (publiek domein)"},"M. Flexor Digitorum Longus":{"bundles":null,"origin":"Achterzijde van de tibia","insertion":"Eindfalanxen van tenen II-V","function":"Flecteert de tenen; ondersteunt de plantairflexie.","direction":"Achter de mediale malleolus naar de teentoppen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray439-Musculus%20flexor%20digitorum%20longus.png","imageCredit":"Gray's Anatomy, H.V. Carter (publiek domein)"},"M. Flexor Hallucis Longus":{"bundles":null,"origin":"Achterzijde van de fibula","insertion":"Eindfalanx van de grote teen","function":"Flecteert de grote teen; ondersteunt de plantairflexie/afzet.","direction":"Achter de enkel naar de grote teen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray439-Musculus%20flexor%20hallucis%20longus.png","imageCredit":"Gray's Anatomy, H.V. Carter (publiek domein)"},"M. Extensor Digitorum Longus":{"bundles":null,"origin":"Laterale tibiacondyl, fibula","insertion":"Dorsale aponeurose van tenen II-V","function":"Strekt de tenen; dorsaalflecteert de enkel.","direction":"Over de voorzijde van het onderbeen naar de teentoppen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Extensor%20digitorum%20longus%20muscle%20-%20animation%202.gif","imageCredit":"Anatomography / BodyParts3D, DBCLS (CC BY-SA 2.1 JP)"},"M. Extensor Hallucis Longus":{"bundles":null,"origin":"Middelste 1/3 van de fibula","insertion":"Eindfalanx van de grote teen","function":"Strekt de grote teen; dorsaalflecteert de enkel.","direction":"Over de voorzijde van het onderbeen naar de grote teen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Extensor%20hallucis%20longus%20muscle%20-%20animation.gif","imageCredit":"Anatomography / BodyParts3D, DBCLS (CC BY-SA 2.1 JP)"}};
const REGIONS={"neck_front":{"cx":100,"cy":45,"label":"Nek (voorzijde)"},"neck_back":{"cx":100,"cy":40,"label":"Nek (achterzijde)"},"shoulder_front":{"cx":65,"cy":70,"label":"Schouder (voorzijde)"},"shoulder_back":{"cx":135,"cy":68,"label":"Schouder / schouderblad (achterzijde)"},"side_chest":{"cx":62,"cy":100,"label":"Zijkant borstkas"},"upper_arm_front":{"cx":38,"cy":120,"label":"Bovenarm (voorzijde)"},"upper_arm_back":{"cx":162,"cy":120,"label":"Bovenarm (achterzijde)"},"forearm_front":{"cx":32,"cy":190,"label":"Onderarm (voorzijde/buigzijde)"},"forearm_back":{"cx":168,"cy":190,"label":"Onderarm (achterzijde/strekzijde)"},"abdomen":{"cx":100,"cy":150,"label":"Buik"},"low_back":{"cx":100,"cy":175,"label":"Onderrug / wervelkolom"},"hip_flexor_front":{"cx":85,"cy":210,"label":"Heup (voorzijde)"},"glute_back":{"cx":115,"cy":215,"label":"Bil / heup (achterzijde)"},"thigh_front":{"cx":85,"cy":270,"label":"Bovenbeen (voorzijde)"},"thigh_medial":{"cx":100,"cy":280,"label":"Bovenbeen (binnenzijde)"},"thigh_back":{"cx":115,"cy":270,"label":"Bovenbeen (achterzijde)"},"knee_back":{"cx":118,"cy":335,"label":"Achterzijde knie"},"calf_back":{"cx":118,"cy":380,"label":"Kuit (achterzijde)"},"shin_front":{"cx":83,"cy":380,"label":"Scheenbeen (voorzijde)"},"calf_lateral":{"cx":125,"cy":370,"label":"Kuit (buitenzijde)"}};
