const GROUPS={"Nek":[{"label":"Voorzijde","muscles":["M. Sternocleidomastoideus","Mm. Scaleni","M. Longus Colli","M. Longus Capitis"]},{"label":"Achterzijde","muscles":["M. Splenius Capitis","M. Splenius Capitis / Cervicis","M. Semispinalis Capitis","Mm. Rotatores"]}],"Borst":[{"label":null,"muscles":["M. Pectoralis Major","M. Pectoralis Minor","M. Serratus Anterior","Mm. Intercostales"]}],"Rug":[{"label":"Bovenrug","muscles":["M. Trapezius","Mm. Rhomboidei","M. Levator Scapulae"]},{"label":"Middenrug","muscles":["M. Latissimus Dorsi","M. Erector Spinae","M. Iliocostalis Thoracis","M. Longissimus Thoracis","M. Spinalis Thoracis","Mm. Rotatores Thoracales"]},{"label":"Onderrug","muscles":["M. Quadratus Lumborum","M. Iliocostalis Lumborum","M. Longissimus Lumborum","M. Multifidus","Mm. Rotatores Lumbales"]}],"Buik & romp":[{"label":null,"muscles":["M. Rectus Abdominis","M. Obliquus Externus Abdominis","M. Obliquus Internus Abdominis","M. Transversus Abdominis"]}],"Armen":[{"label":"Bovenarm & schouder — voorzijde","muscles":["M. Deltoideus","M. Coracobrachialis","M. Subscapularis","M. Biceps Brachii","M. Brachialis"]},{"label":"Bovenarm & schouder — achterzijde","muscles":["M. Supraspinatus","M. Infraspinatus","M. Teres Major","M. Teres Minor","M. Triceps Brachii","M. Anconeus"]},{"label":"Onderarm — voorzijde (buigzijde)","muscles":["M. Brachioradialis","M. Supinator","M. Pronator Teres","M. Pronator Quadratus","M. Flexor Carpi Radialis","M. Flexor Carpi Ulnaris","M. Palmaris Longus","M. Flexor Digitorum Superficialis / Profundus"]},{"label":"Onderarm — achterzijde (strekzijde)","muscles":["M. Extensor Carpi Radialis Longus","M. Extensor Carpi Radialis Longus / Brevis","M. Extensor Carpi Ulnaris","M. Extensor Digitorum","M. Abductor Pollicis Longus","M. Extensor Pollicis Longus"]}],"Heup":[{"label":"Voorzijde","muscles":["M. Psoas Major","M. Iliopsoas","M. Rectus Femoris","M. Sartorius"]},{"label":"Achterzijde","muscles":["M. Gluteus Maximus","M. Piriformis","Diepe pelvitrochantaire spieren","M. Quadratus Femoris","Hamstrings","M. Biceps Femoris","M. Semitendinosus","M. Semimembranosus"]}],"Benen":[{"label":"Voorzijde","muscles":["M. Rectus Femoris","M. Vastus Lateralis / Medialis / Intermedius","M. Sartorius"]},{"label":"Achterzijde","muscles":["Hamstrings","M. Biceps Femoris","M. Semitendinosus","M. Semimembranosus","M. Gastrocnemius","M. Popliteus"]},{"label":"Binnenzijde (adductoren)","muscles":["Adductoren","M. Adductor Magnus","M. Adductor Longus","M. Adductor Brevis","M. Gracilis","M. Pectineus"]},{"label":"Buitenzijde (abductoren)","muscles":["M. Tensor Fasciae Latae","M. Gluteus Medius","M. Gluteus Minimus"]}],"Onderbenen":[{"label":"Voorzijde","muscles":["M. Tibialis Anterior","M. Extensor Digitorum Longus","M. Extensor Hallucis Longus","M. Peroneus Tertius"]},{"label":"Achterzijde","muscles":["M. Gastrocnemius","M. Soleus","M. Triceps Surae","M. Tibialis Posterior","M. Flexor Digitorum Longus","M. Flexor Hallucis Longus","M. Popliteus"]},{"label":"Buitenzijde","muscles":["M. Peroneus Longus","M. Peroneus Brevis","M. Peroneus Longus / Brevis"]}]};
const TESTS={"Nek":[{"id":"spurling","naam":"Spurling's test","beoordeelt":"Cervicale zenuwwortel (cervicaal radiculair syndroom)","waarom":"Uitstralende armpijn of tintelingen kunnen uit de nek komen. Deze test vernauwt het foramen intervertebrale en lokt dan de bekende armklachten uit.","uitvoering":["Cliënt zit rechtop.","Breng de nek in lateroflexie naar de klachtenzijde, eventueel met lichte extensie en rotatie naar dezelfde kant.","Geef voorzichtig axiale druk op het hoofd.","Vraag of de bekende armklachten terugkomen."],"positief":"Herkenbare uitstralende pijn of tintelingen in de arm (passend bij een dermatoom). Alleen lokale nekpijn telt niet als positief.","negatief":"Geen uitstralende armklachten.","gekoppeldeSpieren":["Mm. Scaleni","M. Sternocleidomastoideus"],"structuurType":"neuraal","bronLink":"https://www.physiotutors.com/nl/wiki/spurlings-test-cervical-radicular-syndrome/"},{"id":"cdist","naam":"Cervicale distractietest","beoordeelt":"Cervicale zenuwwortel; ontlasting van het foramen intervertebrale","waarom":"Tegenhanger van de Spurling: door de nek in de lengteas te ontlasten, nemen klachten bij wortelprikkeling juist af.","uitvoering":["Cliënt ligt op de rug (of zit).","Leg één hand onder het achterhoofd en de andere onder de kin.","Trek het hoofd rustig en geleidelijk in de lengteas van de wervelkolom.","Vraag of de armklachten veranderen."],"positief":"Armklachten nemen af of verdwijnen tijdens de tractie.","negatief":"Geen verandering in de klachten.","gekoppeldeSpieren":["M. Sternocleidomastoideus","M. Splenius Capitis","M. Semispinalis Capitis"],"structuurType":"neuraal","bronLink":"https://www.physiotutors.com/nl/wiki/cervical-distraction-test"},{"id":"dnf","naam":"Deep Neck Flexor Endurance Test","beoordeelt":"Uithoudingsvermogen van de diepe nekbuigers","waarom":"Zwakke of snel vermoeide diepe nekbuigers komen vaak voor bij nekpijn en een voorovergestoken hoofdhouding. De test geeft een meetbaar startpunt voor training.","uitvoering":["Cliënt ligt op de rug met gebogen knieën.","Laat de kin intrekken (knikken) en het hoofd ongeveer 2,5 cm van de bank tillen.","Leg je hand onder het achterhoofd en start de stopwatch.","Stop zodra de kin naar voren schuift of het hoofd je hand raakt."],"positief":"Duidelijk korte houdtijd. Ter oriëntatie: mensen zonder nekpijn houden het gemiddeld rond 35–40 s vol, mensen met nekpijn korter (orde 20–25 s). Gebruik de tijd vooral om voortgang te volgen.","negatief":"Houdtijd in de orde van mensen zonder nekklachten, zonder compensatie.","gekoppeldeSpieren":["M. Longus Colli","M. Longus Capitis"],"structuurType":"musculair","bronLink":"https://www.physiotutors.com/wiki/deep-neck-flexor-endurance-test/"}],"Schouder":[{"id":"hawkins-kennedy","naam":"Hawkins-Kennedy Test","beoordeelt":"Subacromiale impingement (M. Supraspinatus pees / bursa)","waarom":"Simuleert de meest voorkomende inklemmingspositie van de supraspinatuspees onder het acromion tijdens overhead-bewegingen — zeer relevant voor overhead-sporters (zwemmen, volleybal, werpen).","uitvoering":["Cliënt zit of staat, arm 90° geflecteerd in de schouder, elleboog 90° gebogen","Trainer stabiliseert de scapula met één hand","Trainer beweegt de arm passief in endorotatie (onderarm naar binnen draaien)"],"positief":"Pijn/onbehagen in de anterolaterale schouder tijdens de endorotatie → wijst op impingement van supraspinatuspees of subacromiale bursa","negatief":"Volledige, pijnvrije endorotatie zonder klachten","gekoppeldeSpieren":["M. Supraspinatus","M. Infraspinatus"],"bronLink":"https://www.physiotutors.com/wiki/hawkins-kennedy-test/"},{"id":"empty-can","naam":"Empty Can Test (Jobe Test)","beoordeelt":"Kracht en integriteit van M. Supraspinatus","waarom":"Isoleert de Supraspinatus door de arm in de 'leegblik'-positie (duim naar beneden) te plaatsen, waarbij de Deltoideus minder kan compenseren dan bij een neutrale positie — hierdoor de meest specifieke krachttest voor deze spier.","uitvoering":["Cliënt staat, armen 90° geabduceerd, 30° horizontaal geflecteerd (in het scapulavlak), duimen naar beneden gedraaid","Trainer oefent van bovenaf neerwaartse druk uit op beide armen","Cliënt weerstaat de druk"],"positief":"Duidelijke zwakte, pijn, of het 'vallen' van de arm t.o.v. de andere zijde → wijst op Supraspinatus-pathologie (tendinopathie of ruptuur)","negatief":"Symmetrische, sterke weerstand zonder pijn","gekoppeldeSpieren":["M. Supraspinatus"],"bronLink":"https://www.physiotutors.com/wiki/empty-can-test/"},{"id":"lift-off","naam":"Lift-Off Test (Gerber's Test)","beoordeelt":"Kracht van M. Subscapularis","waarom":"De enige test die de Subscapularis isoleert in een positie waarin geen andere schouderspier de beweging kan overnemen — de hand loslaten van de rug is alleen mogelijk met actieve endorotatiekracht.","uitvoering":["Cliënt staat, hand op de onderrug (handrug tegen de lumbale wervelkolom), elleboog gebogen","Cliënt tilt de hand actief van de rug af, weg van het lichaam","Bij beperkte schoudermobiliteit: gebruik de Belly Press test als alternatief"],"positief":"Cliënt kan de hand niet van de rug tillen, of alleen met compensatie (elleboog naar achteren) → wijst op Subscapularis-ruptuur/zwakte","negatief":"Hand wordt moeiteloos enkele centimeters van de rug getild","gekoppeldeSpieren":["M. Subscapularis"],"bronLink":"https://www.physiotutors.com/wiki/lift-off-sign/"}],"Rug":[{"id":"slr","naam":"Straight Leg Raise (Lasègue)","beoordeelt":"Lumbosacrale zenuwwortel (L4–S1) en mechanosensitiviteit van de n. ischiadicus","waarom":"Onderscheidt uitstralende beenpijn vanuit een geprikkelde zenuwwortel van gewone stijfheid van de hamstrings.","uitvoering":["Cliënt ligt op de rug, beide benen gestrekt.","Til het been passief en gestrekt op, de heup in neutrale rotatie.","Noteer bij welke hoek klachten ontstaan.","Voeg op die hoek dorsaalflexie van de enkel toe: nemen de klachten toe, dan wijst dat op zenuwweefsel."],"positief":"Herkenbare uitstralende pijn onder de knie, meestal tussen ongeveer 30° en 70° heupflexie, die toeneemt bij dorsaalflexie.","negatief":"Geen beenpijn, of alleen een rekgevoel achter in het bovenbeen dat niet verandert met de enkelstand (hamstrings).","gekoppeldeSpieren":["Hamstrings","M. Gastrocnemius"],"structuurType":"neuraal","bronLink":"https://www.physiotutors.com/nl/wiki/straight-leg-raise-test/"},{"id":"slump","naam":"Slump test","beoordeelt":"Mechanosensitiviteit van het zenuwstelsel (neuraxis en n. ischiadicus)","waarom":"Spant het hele zenuwstelsel stap voor stap aan. Door alleen de nekstand te veranderen zie je of klachten van zenuwweefsel komen of van spieren.","uitvoering":["Cliënt zit op de rand van de bank, handen op de rug.","Laat de romp inzakken (flexie van borst- en lendenwervelkolom); jij houdt die stand vast.","Voeg nekflexie toe, strek dan de knie en trek de voet op.","Laat de nek los (terug naar neutraal) en vraag of de klachten veranderen."],"positief":"Herkenbare klachten die afnemen zodra de nekflexie wordt losgelaten (structurele differentiatie).","negatief":"Alleen rek achter de knie of in de hamstrings die niet verandert met de nekstand.","gekoppeldeSpieren":["Hamstrings","M. Gastrocnemius"],"structuurType":"neuraal","bronLink":"https://www.physiotutors.com/wiki/slump-test/"},{"id":"sorensen","naam":"Biering-Sørensen test","beoordeelt":"Uithoudingsvermogen van de rug- en heupstrekkers","waarom":"Een laag uithoudingsvermogen van de rugstrekkers hangt samen met lage rugklachten. De test is eenvoudig te herhalen en geschikt om trainingsvoortgang te meten.","uitvoering":["Cliënt ligt op de buik, het bovenlichaam vanaf het bekken (spina iliaca anterior superior) over de rand van de bank.","Fixeer de benen ter hoogte van de kuiten, of met een band.","Armen gekruist voor de borst; houd de romp horizontaal.","Meet hoe lang de horizontale stand wordt volgehouden."],"positief":"Snel inzakken, of duidelijk korter dan bij een eerdere meting. Behandel het als aandachtspunt voor training, niet als diagnose.","negatief":"De stand wordt lang en zonder compensatie volgehouden.","gekoppeldeSpieren":["M. Erector Spinae","M. Multifidus","M. Gluteus Maximus","Hamstrings"],"structuurType":"musculair","bronLink":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7246735/"}],"Heup":[{"id":"trendelenburg","naam":"Trendelenburg Test","beoordeelt":"Functie/kracht van M. Gluteus Medius (en M. Gluteus Minimus) als bekkenstabilisator","waarom":"De Gluteus Medius is de belangrijkste frontale-vlak stabilisator van het bekken tijdens de standfase van het lopen. Bij zwakte is dit functioneel direct zichtbaar in de looppas — verklaart vaak klachten aan heup, knie of lage rug bij sporters.","uitvoering":["Cliënt staat rechtop, gewicht op één been, ander been licht gebogen los in de lucht","Trainer kijkt van achteren naar het bekken (SIAS/heupkammen als referentie)","Houd de positie 6 seconden vast","Herhaal aan de andere zijde ter vergelijking"],"positief":"Bekken aan de niet-belaste zijde zakt naar beneden → wijst op zwakte Gluteus Medius aan de belaste (standbeen) zijde. Vaak ook: Duchenne-hink of balansverlies","negatief":"Bekken blijft horizontaal, SIAS beide zijden gelijke hoogte, stabiel gedurende 6 sec","gekoppeldeSpieren":["M. Gluteus Medius","M. Gluteus Minimus","M. Tensor Fasciae Latae"],"bronLink":"https://www.physiotutors.com/wiki/trendelenburg-sign/"},{"id":"thomas","naam":"Thomas Test","beoordeelt":"Verkorting van M. Iliopsoas en M. Rectus Femoris (heupflexoren)","waarom":"Door het bekken vlak te fixeren (contralaterale heup maximaal geflecteerd tegen de borst) wordt lumbale compensatie uitgeschakeld, waardoor alleen de werkelijke lengte van de heupflexoren wordt gemeten.","uitvoering":["Cliënt ligt op de rug aan het einde van de behandeltafel","Cliënt trekt één knie actief naar de borst en houdt deze vast (fixeert bekken/lumbale wervelkolom)","Het andere been hangt vrij over de rand van de tafel","Trainer observeert hoek en positie van het hangende been"],"positief":"Dij blijft omhoog staan → verkorte M. Iliopsoas. Onderbeen strekt actief → verkorte M. Rectus Femoris. Dij beweegt naar buiten (abductie) → verkorte M. Tensor Fasciae Latae","negatief":"Dij zakt volledig horizontaal en de knie hangt ontspannen in ~90° flexie","gekoppeldeSpieren":["M. Iliopsoas","M. Rectus Femoris","M. Tensor Fasciae Latae"],"bronLink":"https://www.physiotutors.com/wiki/thomas-test/"},{"id":"faber","naam":"FABER Test (Patrick's Test)","beoordeelt":"Heupgewrichtsmobiliteit, adductor-verkorting, en SI-gewrichtsprovocatie","waarom":"De gecombineerde beweging (Flexie-ABductie-Exorotatie) ontdekt zowel gewrichtsbeperkingen als spierverkorting van de mediale heupspieren in één vloeiende test — snel en functioneel bruikbaar zonder apparatuur.","uitvoering":["Cliënt ligt op de rug","Enkel van het te testen been op de knie van het andere been plaatsen ('figuur 4'-positie)","Trainer duwt de geflecteerde knie voorzichtig richting de tafel"],"positief":"Knie blijft duidelijk hoger dan andere zijde → verkorte adductoren of gewrichtsbeperking. Pijn in de lies → heupgewrichtspathologie. Pijn in onderrug/bekken → SI-gewrichtsprobleem","negatief":"Knie zakt nagenoeg symmetrisch tot vlak bij de tafel, pijnvrij","gekoppeldeSpieren":["M. Adductor Magnus","M. Adductor Longus","M. Adductor Brevis","M. Gracilis"],"bronLink":"https://www.physiotutors.com/wiki/patricks-test/"}],"Knie":[{"id":"lachman","naam":"Lachman Test","beoordeelt":"Integriteit van de Voorste Kruisband (VKB)","waarom":"Klinisch en wetenschappelijk aangetoond als de meest sensitieve test voor VKB-letsel — lichte knieflexie (20-30°) voorkomt dat de hamstrings de anterieure translatie blokkeren, in tegenstelling tot de Anterior Drawer test bij 90°.","uitvoering":["Cliënt ligt op de rug, knie in 20-30° flexie, been ontspannen","Trainer stabiliseert het femur met één hand","Trainer trekt de tibia met de andere hand naar voren"],"positief":"Duidelijke voorwaartse verschuiving van de tibia zonder hard eindgevoel (soft end-feel) t.o.v. de andere knie → wijst op VKB-ruptuur","negatief":"Minimale translatie met een stevig, hard eindgevoel","gekoppeldeSpieren":["Hamstrings"],"structuurType":"ligamentair","bronLink":"https://www.physiotutors.com/wiki/lachman-test/"},{"id":"thessaly","naam":"Thessaly Test","beoordeelt":"Meniscusletsel (mediaal/lateraal)","waarom":"In tegenstelling tot de klassieke McMurray-test (liggend, passief) wordt deze test staand en belast uitgevoerd — bootst functionele, sportspecifieke rotatiebelasting na met hogere sensitiviteit/specificiteit in de praktijk.","uitvoering":["Cliënt staat op één been (te testen zijde), trainer ondersteunt eventueel de handen voor balans","Cliënt buigt de knie licht (5° en daarna 20°)","Cliënt draait romp en knie heen en weer terwijl voetcontact behouden blijft"],"positief":"Pijn in de gewrichtsspleet (mediaal of lateraal), eventueel gevoel van 'vastzitten' → wijst op meniscusscheur aan die zijde","negatief":"Vloeiende rotatie zonder pijn of mechanisch slotgevoel","gekoppeldeSpieren":["M. Popliteus"],"structuurType":"meniscus/gewricht","bronLink":"https://www.physiotutors.com/wiki/thessaly-test/"},{"id":"valgus-stress","naam":"Valgus Stress Test","beoordeelt":"Integriteit van de Mediale Collaterale Band (MCL)","waarom":"Directe, gerichte belasting van de mediale gewrichtslijn in lichte flexie (20-30°) sluit de stabiliserende rol van kniekapsel/kruisbanden grotendeels uit, waardoor specifiek de MCL wordt beoordeeld.","uitvoering":["Cliënt ligt op de rug, knie in 20-30° flexie","Trainer plaatst één hand lateraal aan de knie, de andere hand mediaal aan de enkel","Trainer oefent een valgusdruk uit (mediale opening forceren)"],"positief":"Overmatige mediale gewrichtsopening en/of pijn t.o.v. de andere knie → wijst op MCL-letsel (graad I-III)","negatief":"Minimale opening, stevig eindgevoel, geen pijn","gekoppeldeSpieren":["M. Gracilis","Hamstrings"],"structuurType":"ligamentair","bronLink":"https://www.physiotutors.com/wiki/valgus-stress-test/"}],"Enkel":[{"id":"adt","naam":"Anterior drawer test (enkel)","beoordeelt":"Lig. talofibulare anterius (ATFL)","waarom":"Het ATFL scheurt het vaakst bij een inversietrauma. Laxiteit van deze band verklaart instabiliteit en herhaald omzwikken.","uitvoering":["Cliënt ligt of zit, knie licht gebogen, enkel in ongeveer 10–20° plantairflexie.","Fixeer met één hand de onderkant van het onderbeen.","Omvat met de andere hand de hiel en trek de voet naar voren.","Vergelijk altijd met de andere enkel."],"positief":"Meer voorwaartse verplaatsing dan aan de andere zijde en/of een zacht eindgevoel; soms een kuiltje lateraal (dimple sign).","negatief":"Gelijke verplaatsing als aan de andere zijde met een vast eindgevoel.","gekoppeldeSpieren":["M. Peroneus Longus","M. Peroneus Brevis"],"structuurType":"ligamentair","bronLink":"https://www.physiotutors.com/nl/wiki/anterior-drawer-test-ankle/"},{"id":"tilt","naam":"Talar tilt test","beoordeelt":"Lig. calcaneofibulare (CFL)","waarom":"Bij zwaarder inversieletsel scheurt na het ATFL ook het CFL. Deze test vult de anterior drawer aan.","uitvoering":["Cliënt ligt of zit, enkel in neutrale stand (90°).","Fixeer het onderbeen met één hand.","Kantel met de andere hand de hiel en talus in inversie.","Vergelijk met de andere enkel."],"positief":"Meer kanteling dan aan de andere zijde en/of een zacht eindgevoel.","negatief":"Gelijke kanteling met een vast eindgevoel.","gekoppeldeSpieren":["M. Peroneus Longus","M. Peroneus Brevis"],"structuurType":"ligamentair","bronLink":"https://www.physiotutors.com/nl/wiki/talar-tilt-test/"},{"id":"thompson","naam":"Thompson test","beoordeelt":"Continuïteit van de achillespees","waarom":"Een achillespeesruptuur wordt makkelijk gemist omdat de cliënt de voet vaak nog met andere spieren kan strekken. Deze test sluit dat snel uit.","uitvoering":["Cliënt ligt op de buik met de voeten over de rand van de bank (of knielt op een stoel).","Knijp stevig in de kuitbuik.","Kijk of de voet daarbij een plantairflexie maakt.","Vergelijk met de andere zijde."],"positief":"Geen of duidelijk minder plantairflexie bij het knijpen: verdenking op een ruptuur. Direct doorverwijzen.","negatief":"De voet beweegt duidelijk in plantairflexie.","gekoppeldeSpieren":["M. Gastrocnemius","M. Soleus","M. Triceps Surae"],"structuurType":"tendineus","bronLink":"https://www.physiotutors.com/nl/wiki/thompson-test/"}]};

